// Run:  node tools/build-vocab.js
// Inputs (you provide):
//   content/oxford.csv    columns: ,word,type,cefr,phon_br,phon_n_am,definition,example,uk,us
//   content/meanings.csv  columns: id,meaning     (id = the order number from oxford.csv; one row per word you have a meaning for)
// Outputs:
//   content/vocab.js          word list the site reads (do not edit by hand)
//   content/vocab-def.js      meanings the site reads (do not edit by hand)
//   content/word-notes.csv    NOTES FOR YOU ONLY: order, word, type, cefr for every word, handy for generating meanings. The site never reads it.
// Words without a row in meanings.csv simply have no meaning yet.
const fs = require('fs'), path = require('path');
const dir = path.join(__dirname, '..', 'content');

function parseCsv(text) {
  const rows = []; let row = [], f = '', q = false;
  text = text.replace(/^﻿/, '');
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"') { if (text[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += c; }
    else if (c === '"') q = true;
    else if (c === ',') { row.push(f); f = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(f); f = ''; if (row.length > 1 || row[0] !== '') rows.push(row); row = []; }
    else f += c;
  }
  if (f !== '' || row.length) { row.push(f); rows.push(row); }
  return rows;
}
const csvField = v => /[",\n\r]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v;
function readTable(file) {
  if (!fs.existsSync(file)) return [];
  const rows = parseCsv(fs.readFileSync(file, 'utf8'));
  if (!rows.length) return [];
  const head = rows[0].map(h => h.trim().toLowerCase());
  return rows.slice(1).map(r => { const o = {}; head.forEach((h, i) => { o[h === '' ? 'order' : h] = (r[i] || '').trim(); }); return o; });
}

const oxford = readTable(path.join(dir, 'oxford.csv'));
if (!oxford.length) { console.error('ERROR: content/oxford.csv is missing or empty.'); process.exit(1); }
const meanings = {};
readTable(path.join(dir, 'meanings.csv')).forEach(r => {
  const id = r.id !== undefined ? r.id : r.order, m = r.meaning !== undefined ? r.meaning : (r.def !== undefined ? r.def : r.definition);
  if (id !== undefined && id !== '' && m) meanings[id] = m;
});

const words = [], defs = {}, noteRows = [[ 'id', 'word', 'type', 'cefr' ]], known = new Set();
let skipped = 0;
oxford.forEach(r => {
  const order = parseInt(r.order, 10), cefr = (r.cefr || '').toUpperCase();
  if (!(order >= 0) || !r.word || !/^[A-C][12]$/.test(cefr)) { skipped++; console.warn('skipped row (needs order, word, cefr A1-C2): ' + JSON.stringify(r).slice(0, 120)); return; }
  words.push([order, r.word, r.type || '', cefr, r.phon_n_am || r.phon_br || '', r.uk || '', r.us || '']);
  known.add(String(order));
  noteRows.push([String(order), r.word, r.type || '', cefr]);
});
Object.keys(meanings).forEach(k => { defs[k] = meanings[k]; });  /* every meaning is kept, matched to words by id only; ids with no word show up in the Admin page */
Object.keys(meanings).forEach(k => known.has(k) || console.warn('warn: meanings.csv has id ' + k + ' but oxford.csv has no such order number'));

const head = '/* GENERATED by tools/build-vocab.js from content/oxford.csv - do not edit by hand. Each row: [order, word, type, cefr, American phonetic, UK audio file, US audio file]. */\n';
fs.writeFileSync(path.join(dir, 'vocab.js'), head + 'window.OEL = window.OEL || {};\nOEL.vocab = [\n' + words.map(w => '  ' + JSON.stringify(w)).join(',\n') + '\n];\n');
const dhead = '/* GENERATED by tools/build-vocab.js from content/meanings.csv - do not edit by hand. Key = order number. Words not listed here have no meaning yet. */\n';
fs.writeFileSync(path.join(dir, 'vocab-def.js'), dhead + 'window.OEL = window.OEL || {};\nOEL.vocabDef = {\n' + Object.keys(defs).map(k => '  ' + k + ': ' + JSON.stringify(defs[k])).join(',\n') + '\n};\n');
fs.writeFileSync(path.join(dir, 'word-notes.csv'), noteRows.map(r => r.map(csvField).join(',')).join('\n') + '\n');
console.log('vocab.js: ' + words.length + ' words' + (skipped ? ' (' + skipped + ' skipped)' : '') + '. meanings with a matching word: ' + words.filter(w => defs[w[0]]).length + ' of ' + words.length + '.');
